ALTER TABLE "payment_disputes" ADD COLUMN "decided_by" uuid;--> statement-breakpoint
ALTER TABLE "payment_disputes" ADD COLUMN "decided_at" timestamp with time zone;--> statement-breakpoint
ALTER TABLE "payment_disputes" ADD CONSTRAINT "payment_disputes_decided_by_users_id_fk" FOREIGN KEY ("decided_by") REFERENCES "public"."users"("id") ON DELETE restrict ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "email_outbox" ADD CONSTRAINT "email_outbox_kind_check" CHECK ("email_outbox"."kind" in ('listing-submitted', 'listing-approved', 'listing-changes-requested', 'onboarding-reminder', 'booking-confirmed', 'booking-cancelled', 'booking-payment-refunded', 'booking-received', 'booking-cancelled-by-driver', 'booking-cancelled-by-team', 'listing-invite', 'listing-handover-offered', 'listing-handover-accepted', 'two-factor-removed', 'listing-suspended', 'listing-reinstated', 'account-suspended', 'account-reinstated', 'booking-cancelled-by-staff', 'dispute-decided'));--> statement-breakpoint
ALTER TABLE "bookings" ADD CONSTRAINT "bookings_refund_status_check" CHECK ("bookings"."refund_status" is null or ("bookings"."refund_status" in ('owed', 'sent', 'failed', 'settled') and "bookings"."status" = 'cancelled' and "bookings"."payment_status" = 'succeeded' and "bookings"."refund_minor" is not null and "bookings"."refund_minor" > 0 and ("bookings"."refund_status" in ('sent', 'failed', 'settled')) = ("bookings"."stripe_refund_id" is not null)));--> statement-breakpoint
ALTER TABLE "payment_disputes" ADD CONSTRAINT "payment_disputes_decision_check" CHECK (("payment_disputes"."decision" is null and "payment_disputes"."decided_by" is null and "payment_disputes"."decided_at" is null) or ("payment_disputes"."decision" in ('parkfairy_bears', 'owners_bear') and "payment_disputes"."status" = 'lost' and "payment_disputes"."decided_by" is not null and "payment_disputes"."decided_at" is not null));--> statement-breakpoint
ALTER TABLE "audit_log" ADD CONSTRAINT "audit_log_action_check" CHECK ("audit_log"."action" in ('listing.approved', 'listing.changes_requested', 'listing.proof_opened', 'user.two_factor_removed', 'user.viewed', 'listing.suspended', 'listing.reinstated', 'user.suspended', 'user.reinstated', 'booking.viewed', 'booking.cancelled', 'booking.refund_retried', 'booking.refund_settled', 'dispute.decided'));--> statement-breakpoint
ALTER TABLE "audit_log" ADD CONSTRAINT "audit_log_target_type_check" CHECK ("audit_log"."target_type" in ('listing', 'user', 'booking', 'dispute'));